import React, { useState, useEffect } from 'react';

const classSpecs = {
  'Death Knight': ['Blood', 'Frost', 'Unholy'],
  'Demon Hunter': ['Havoc', 'Vengeance'],
  'Druid': ['Balance', 'Feral', 'Guardian', 'Restoration'],
  'Evoker': ['Devastation', 'Preservation', 'Augmentation'],
  'Hunter': ['Beast Mastery', 'Marksmanship', 'Survival'],
  'Mage': ['Arcane', 'Fire', 'Frost'],
  'Monk': ['Brewmaster', 'Mistweaver', 'Windwalker'],
  'Paladin': ['Holy', 'Protection', 'Retribution'],
  'Priest': ['Discipline', 'Holy', 'Shadow'],
  'Rogue': ['Assassination', 'Outlaw', 'Subtlety'],
  'Shaman': ['Elemental', 'Enhancement', 'Restoration'],
  'Warlock': ['Affliction', 'Demonology', 'Destruction'],
  'Warrior': ['Arms', 'Fury', 'Protection']
};

function WowPlayerSearchInput() {
  const [tailwindLoaded, setTailwindLoaded] = useState(false);
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedSpec, setSelectedSpec] = useState('');
  const [contentType, setContentType] = useState('3v3');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Use global storage to share data with display widget
  const [playerData, setPlayerData] = useGlobalStorage('wowPlayerSearch', null);

  useEffect(() => {
    if (!document.getElementById('tailwind-script')) {
      const tailwindScript = document.createElement('script');
      tailwindScript.id = 'tailwind-script';
      tailwindScript.src = 'https://cdn.tailwindcss.com';
      tailwindScript.onload = () => {
        setTimeout(() => setTailwindLoaded(true), 100);
      };
      document.head.appendChild(tailwindScript);
    } else {
      setTailwindLoaded(true);
    }
  }, []);

  const scrapeMurlok = async () => {
    if (!selectedClass || !selectedSpec) {
      setError('Please select both a class and specialization');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const classFormatted = selectedClass.toLowerCase().replace(/\s+/g, '-');
      const specFormatted = selectedSpec.toLowerCase().replace(/\s+/g, '-');
      const targetUrl = `https://murlok.io/${classFormatted}/${specFormatted}/${contentType}`;

      console.log('Fetching from:', targetUrl);

      const response = await miyagiAPI.post('search-web-raw', {
        searchPrompt: `${targetUrl}`,
        count: 1
      });

      if (response.sources && response.sources.length > 0) {
        const topResult = response.sources[0];
        const extractedText = topResult.extractedText || topResult.snippet || '';

        const topPlayers = extractTopPlayers(extractedText, topResult.url);

        const playersWithLinks = topPlayers.map(player => {
          const raiderioUrl = convertToRaiderIO(player.url, player.name);
          const checkPvpUrl = convertToCheckPvP(player.region, player.realm, player.name);
          return {
            ...player,
            raiderioUrl,
            checkPvpUrl
          };
        });

        // Send top 5 players to display widget via global storage
        const topFivePlayers = playersWithLinks.slice(0, 5);
        setPlayerData({
          players: topFivePlayers,
          class: selectedClass,
          spec: selectedSpec,
          contentType: contentType,
          timestamp: Date.now()
        });
      } else {
        setError('No results found on murlok.io for this class/spec combination');
      }
    } catch (err) {
      console.error('Error during scraping:', err);
      setError(err.message || 'Failed to scrape data from murlok.io');
    } finally {
      setLoading(false);
    }
  };

  const extractTopPlayers = (text, baseUrl) => {
    const players = [];
    const seen = new Set();

    const playerPattern = /([A-Z][a-záàâäãåçéèêëíìîïñóòôöõúùûüýÿæœ]+(?:[a-z]+)?)\s+([A-Z][a-zA-Z\s-]+?)\s+\(([A-Z]{2})\)/gi;

    const matches = [...text.matchAll(playerPattern)];
    console.log('Found player text matches:', matches.length);

    for (const match of matches) {
      const [fullMatch, playerName, realm, region] = match;
      const characterKey = `${playerName}-${realm}-${region}`.toLowerCase();

      if (!seen.has(characterKey)) {
        seen.add(characterKey);

        const realmUrl = realm.trim().toLowerCase().replace(/\s+/g, '-');
        const playerUrl = playerName.toLowerCase();
        const regionUrl = region.toLowerCase();

        players.push({
          name: playerName.trim(),
          region: region.toUpperCase(),
          realm: realm.trim(),
          url: `https://murlok.io/character/${regionUrl}/${realmUrl}/${playerUrl}/pvp`,
          rank: players.length + 1
        });
      }
    }

    console.log('Total players extracted:', players.length);
    return players;
  };

  const convertToRaiderIO = (murlokUrl, characterName) => {
    const match = murlokUrl.match(/\/character\/([a-z]+)\/([a-z0-9-]+)\/([^/]+)/i);

    if (match) {
      const [, region, realm, character] = match;
      const capitalizedName = character.charAt(0).toUpperCase() + character.slice(1);
      return `https://raider.io/characters/${region}/${realm}/${capitalizedName}`;
    }

    return murlokUrl;
  };

  const convertToCheckPvP = (region, realm, characterName) => {
    const capitalizedRealm = realm
      .split('-')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join('-');

    return `https://check-pvp.fr/${region.toLowerCase()}/${capitalizedRealm}/${characterName}`;
  };

  if (!tailwindLoaded) {
    return <div style={{ padding: '20px', textAlign: 'center', color: '#666' }}>Loading...</div>;
  }

  return (
    <div style={{ 
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
      padding: '40px',
      height: '100%',
      overflow: 'auto',
      background: '#fafafa'
    }}>
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl font-semibold text-gray-800 mb-1">Find Class Info</h1>
        <p className="text-sm text-gray-500">Get all your World of Warcraft Info in one place!</p>
      </div>

      {/* Selection Form */}
      <div className="bg-white rounded-lg border border-gray-200 p-6 mb-6">
        <div className="space-y-5">
          {/* Class Selection */}
          <div>
            <label className="block text-xs font-medium text-gray-600 mb-2 uppercase tracking-wide">
              Class
            </label>
            <select
              value={selectedClass}
              onChange={(e) => {
                setSelectedClass(e.target.value);
                setSelectedSpec('');
              }}
              className="w-full px-4 py-2.5 bg-white border border-gray-300 rounded-md text-gray-800 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
            >
              <option value="">Select a class...</option>
              {Object.keys(classSpecs).map(cls => (
                <option key={cls} value={cls}>{cls}</option>
              ))}
            </select>
          </div>

          {/* Spec Selection */}
          {selectedClass && (
            <div>
              <label className="block text-xs font-medium text-gray-600 mb-2 uppercase tracking-wide">
                Specialization
              </label>
              <select
                value={selectedSpec}
                onChange={(e) => setSelectedSpec(e.target.value)}
                className="w-full px-4 py-2.5 bg-white border border-gray-300 rounded-md text-gray-800 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
              >
                <option value="">Select a spec...</option>
                {classSpecs[selectedClass].map(spec => (
                  <option key={spec} value={spec}>{spec}</option>
                ))}
              </select>
            </div>
          )}

          {/* Content Type Selection */}
          {selectedSpec && (
            <div>
              <label className="block text-xs font-medium text-gray-600 mb-2 uppercase tracking-wide">
                Content Type
              </label>
              <div className="flex gap-3">
                <button
                  onClick={() => setContentType('3v3')}
                  className={`flex-1 px-4 py-2.5 rounded-md text-sm font-medium transition-all ${
                    contentType === '3v3'
                      ? 'bg-blue-600 text-white'
                      : 'bg-white text-gray-700 border border-gray-300 hover:border-gray-400'
                  }`}
                >
                  3v3 Arena
                </button>
                <button
                  onClick={() => setContentType('m+')}
                  className={`flex-1 px-4 py-2.5 rounded-md text-sm font-medium transition-all ${
                    contentType === 'm+'
                      ? 'bg-blue-600 text-white'
                      : 'bg-white text-gray-700 border border-gray-300 hover:border-gray-400'
                  }`}
                >
                  Mythic+
                </button>
              </div>
            </div>
          )}

          {/* Submit Button */}
          <button
            onClick={scrapeMurlok}
            disabled={!selectedClass || !selectedSpec || loading}
            className="w-full px-6 py-3 bg-blue-600 text-white font-medium text-sm rounded-md hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed transition-all"
          >
            {loading ? 'Searching...' : 'Find Spec Resources'}
          </button>
        </div>
      </div>

      {/* Error Display */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-md p-4">
          <p className="text-red-700 text-sm">{error}</p>
        </div>
      )}
    </div>
  );
}

export default WowPlayerSearchInput;

import React, { useState, useEffect } from 'react';

function WowMediaGuides() {
  const [tailwindLoaded, setTailwindLoaded] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [youtubeVideos, setYoutubeVideos] = useState([]);

  // Read from global storage to sync with search widget
  const [playerData] = useGlobalStorage('wowPlayerSearch', null);

  useEffect(() => {
    if (!document.getElementById('tailwind-script')) {
      const tailwindScript = document.createElement('script');
      tailwindScript.id = 'tailwind-script';
      tailwindScript.src = 'https://cdn.tailwindcss.com';
      tailwindScript.onload = () => {
        setTimeout(() => setTailwindLoaded(true), 100);
      };
      document.head.appendChild(tailwindScript);
    } else {
      setTailwindLoaded(true);
    }
  }, []);

  // Fetch media when playerData changes
  useEffect(() => {
    if (playerData && playerData.class && playerData.spec) {
      fetchMediaGuides();
    }
  }, [playerData]);

  const fetchMediaGuides = async () => {
    if (!playerData || !playerData.class || !playerData.spec) {
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const searchQuery = `${playerData.spec} ${playerData.class} WoW guide youtube`;

      // Fetch YouTube videos using video search API
      let youtubeData = [];
      try {
        const response = await miyagiAPI.post('search-videos', {
          searchPrompt: searchQuery,
          count: 10
        });

        // autoRoutes wraps response in { success, data: { assets, ... } }
        const assets = response?.data?.assets || response?.assets || [];
        if (assets && Array.isArray(assets) && assets.length > 0) {
          youtubeData = assets
            .filter(video => video.url && video.url.includes('youtube.com'))
            .map(video => {
              // Extract video ID from URL
              const videoId = video.url?.split('v=')[1]?.split('&')[0] || '';

              return {
                videoId,
                title: video.title || 'Video Guide',
                channelTitle: video.channelName || video.author || video.attribution || '',
                thumbnail: video.thumbnailUrl || video.thumbnail || video.image || '',
                description: video.description || video.snippet || '',
                url: video.url
              };
            });
        }
      } catch (searchError) {
        console.error('Video search error:', searchError);
      }

      setYoutubeVideos(youtubeData);

      if (youtubeData.length === 0) {
        setError('No YouTube guides found. Try a different class/spec.');
      }
    } catch (err) {
      console.error('Error fetching media:', err);
      setError(err.message || 'Failed to fetch guides');
    } finally {
      setLoading(false);
    }
  };

  if (!tailwindLoaded) {
    return <div style={{ padding: '20px', textAlign: 'center', color: '#666' }}>Loading...</div>;
  }

  if (!playerData || !playerData.class || !playerData.spec) {
    return (
      <div style={{ 
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
        padding: '40px',
        height: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: '#fafafa'
      }}>
        <div className="text-center">
          <div className="text-gray-400 text-4xl mb-3">{'\u{1F3AC}'}</div>
          <p className="text-gray-500 text-sm">No class selected</p>
          <p className="text-gray-400 text-xs mt-1">Search for a class to see video guides</p>
        </div>
      </div>
    );
  }

  return (
    <div style={{ 
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
      padding: '40px',
      height: '100%',
      overflow: 'auto',
      background: '#fafafa'
    }}>
      {/* Header */}
      <div className="mb-6">
        <h1 className="text-2xl font-semibold text-gray-800 mb-1">YouTube Guides</h1>
        <p className="text-sm text-gray-500">
          {playerData.class} {'\u{2022}'} {playerData.spec}
        </p>
      </div>

      {loading && (
        <div className="bg-white rounded-lg border border-gray-200 p-8 text-center">
          <div className="text-red-600 text-sm font-medium">Loading videos...</div>
        </div>
      )}

      {error && (
        <div className="bg-red-50 border border-red-200 rounded-md p-4 mb-6">
          <p className="text-red-700 text-sm">{error}</p>
        </div>
      )}

      {!loading && (
        <div className="space-y-3">
          {youtubeVideos.length > 0 ? (
            youtubeVideos.map((video, index) => (
              <div key={index} className="bg-white rounded-lg border border-gray-200 p-4 hover:border-gray-300 transition-all">
                <div className="flex gap-4">
                  {/* Thumbnail */}
                  {video.thumbnail && (
                    <a 
                      href={video.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex-shrink-0"
                    >
                      <img 
                        src={video.thumbnail} 
                        alt={video.title}
                        className="w-40 h-24 object-cover rounded hover:opacity-90 transition-opacity"
                      />
                    </a>
                  )}

                  {/* Content */}
                  <div className="flex-1 min-w-0">
                    <a
                      href={video.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="block"
                    >
                      <h3 className="text-sm font-semibold text-gray-800 mb-1 line-clamp-2 hover:text-red-600 transition-colors">
                        {video.title}
                      </h3>
                    </a>
                    {video.channelTitle && (
                      <div className="text-xs text-gray-500 mb-2">
                        {video.channelTitle}
                      </div>
                    )}
                    {video.description && (
                      <p className="text-xs text-gray-600 line-clamp-2 mb-3">
                        {video.description}
                      </p>
                    )}
                    <a
                      href={video.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-block px-3 py-1.5 bg-red-600 text-white rounded text-xs font-medium hover:bg-red-700 transition-colors"
                    >
                      Watch on YouTube
                    </a>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="bg-white rounded-lg border border-gray-200 p-8 text-center">
              <div className="text-gray-400 text-3xl mb-2">{'\u{1F4FA}'}</div>
              <p className="text-gray-500 text-sm">No YouTube guides found</p>
              <p className="text-gray-400 text-xs mt-1">Try a different class or spec</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default WowMediaGuides;

import React, { useState, useEffect } from 'react';

function WowGuides() {
  const [tailwindLoaded, setTailwindLoaded] = useState(false);

  // Read from global storage to sync with search widget
  const [playerData] = useGlobalStorage('wowPlayerSearch', null);

  useEffect(() => {
    if (!document.getElementById('tailwind-script')) {
      const tailwindScript = document.createElement('script');
      tailwindScript.id = 'tailwind-script';
      tailwindScript.src = 'https://cdn.tailwindcss.com';
      tailwindScript.onload = () => {
        setTimeout(() => setTailwindLoaded(true), 100);
      };
      document.head.appendChild(tailwindScript);
    } else {
      setTailwindLoaded(true);
    }
  }, []);

  const formatForUrl = (text) => {
    return text.toLowerCase().replace(/\s+/g, '-');
  };

  const generateGuides = () => {
    if (!playerData || !playerData.class || !playerData.spec) {
      return null;
    }

    const classUrl = formatForUrl(playerData.class);
    const specUrl = formatForUrl(playerData.spec);

    return {
      wowhead: `https://www.wowhead.com/guide/classes/${classUrl}/${specUrl}/overview-pve-dps`,
      icyVeinsPve: `https://www.icy-veins.com/wow/${specUrl}-${classUrl}-pve-dps-guide`,
      icyVeinsPvp: `https://www.icy-veins.com/wow/${specUrl}-${classUrl}-pvp-guide`
    };
  };

  const guides = generateGuides();

  if (!tailwindLoaded) {
    return <div style={{ padding: '20px', textAlign: 'center', color: '#666' }}>Loading...</div>;
  }

  return (
    <div style={{ 
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
      padding: '40px',
      height: '100%',
      overflow: 'auto',
      background: '#fafafa'
    }}>
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl font-semibold text-gray-800 mb-1">Class Guides</h1>
        {playerData && playerData.class && playerData.spec ? (
          <p className="text-sm text-gray-500">
            {playerData.class} {'\u{2022}'} {playerData.spec}
          </p>
        ) : (
          <p className="text-sm text-gray-500">Search for a class to see guides</p>
        )}
      </div>

      {/* Guide Links */}
      {guides ? (
        <div className="space-y-3">
          <div className="bg-white rounded-lg border border-gray-200 p-5 hover:border-gray-300 transition-all">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-base font-semibold text-gray-800 mb-0.5">Wowhead Guide</h3>
                <p className="text-xs text-gray-500">PvE DPS Overview</p>
              </div>
              <a
                href={guides.wowhead}
                target="_blank"
                rel="noopener noreferrer"
                className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium hover:bg-blue-700 transition-all"
              >
                Open Guide
              </a>
            </div>
          </div>

          <div className="bg-white rounded-lg border border-gray-200 p-5 hover:border-gray-300 transition-all">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-base font-semibold text-gray-800 mb-0.5">Icy Veins PvE</h3>
                <p className="text-xs text-gray-500">PvE DPS Guide</p>
              </div>
              <a
                href={guides.icyVeinsPve}
                target="_blank"
                rel="noopener noreferrer"
                className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium hover:bg-blue-700 transition-all"
              >
                Open Guide
              </a>
            </div>
          </div>

          <div className="bg-white rounded-lg border border-gray-200 p-5 hover:border-gray-300 transition-all">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-base font-semibold text-gray-800 mb-0.5">Icy Veins PvP</h3>
                <p className="text-xs text-gray-500">PvP Guide</p>
              </div>
              <a
                href={guides.icyVeinsPvp}
                target="_blank"
                rel="noopener noreferrer"
                className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium hover:bg-blue-700 transition-all"
              >
                Open Guide
              </a>
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-lg border border-gray-200 p-8 text-center">
          <div className="text-gray-400 text-3xl mb-2">{'\u{1F4DA}'}</div>
          <p className="text-gray-500 text-sm">Search for a class in the search widget to view guides</p>
        </div>
      )}
    </div>
  );
}

export default WowGuides;

import React, { useState, useEffect } from 'react';

function WowPlayerDisplay() {
  const [tailwindLoaded, setTailwindLoaded] = useState(false);

  // Read player data from global storage
  const [data] = useGlobalStorage('wowPlayerSearch', null);

  useEffect(() => {
    if (!document.getElementById('tailwind-script')) {
      const tailwindScript = document.createElement('script');
      tailwindScript.id = 'tailwind-script';
      tailwindScript.src = 'https://cdn.tailwindcss.com';
      tailwindScript.onload = () => {
        setTimeout(() => setTailwindLoaded(true), 100);
      };
      document.head.appendChild(tailwindScript);
    } else {
      setTailwindLoaded(true);
    }
  }, []);

  if (!tailwindLoaded) {
    return <div style={{ padding: '20px', textAlign: 'center', color: '#666' }}>Loading...</div>;
  }

  if (!data || !data.players || data.players.length === 0) {
    return (
      <div style={{ 
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
        padding: '40px',
        height: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: '#fafafa'
      }}>
        <div className="text-center">
          <div className="text-gray-400 text-4xl mb-3">{'\u{1F50D}'}</div>
          <p className="text-gray-500 text-sm">No players to display</p>
          <p className="text-gray-400 text-xs mt-1">Search for players using the input widget</p>
        </div>
      </div>
    );
  }

  return (
    <div style={{ 
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
      padding: '40px',
      height: '100%',
      overflow: 'auto',
      background: '#fafafa'
    }}>
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl font-semibold text-gray-800 mb-1">Top 5 Players</h1>
        <p className="text-sm text-gray-500">
          {data.class} {'\u{2022}'} {data.spec} {'\u{2022}'} {data.contentType === '3v3' ? '3v3 Arena' : 'Mythic+'}
        </p>
      </div>

      {/* Players List */}
      <div className="space-y-3">
        {data.players.map((player, index) => (
          <div 
            key={index}
            className="bg-white rounded-lg border border-gray-200 p-5 hover:border-gray-300 transition-all"
          >
            <div className="flex items-center gap-4">
              {/* Rank Badge */}
              <div className="flex-shrink-0">
                <div className="w-10 h-10 rounded-full bg-blue-600 flex items-center justify-center text-white font-semibold text-sm">
                  #{player.rank}
                </div>
              </div>

              <div className="flex-1 min-w-0">
                <h3 className="text-base font-semibold text-gray-800 mb-0.5">{player.name}</h3>
                <p className="text-xs text-gray-500">
                  {player.realm} {'\u{2022}'} {player.region}
                </p>
              </div>

              <div className="flex flex-wrap gap-2">
                <a
                  href={player.raiderioUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="px-3 py-1.5 bg-green-600 text-white rounded text-xs font-medium hover:bg-green-700 transition-all"
                >
                  Raider.IO
                </a>
                <a
                  href={player.checkPvpUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="px-3 py-1.5 bg-purple-600 text-white rounded text-xs font-medium hover:bg-purple-700 transition-all"
